  ensurePersistence(){fs.mkdirSync(this.dataDir,{recursive:true});fs.mkdirSync(this.recoveryDir,{recursive:true});}
  load(){if(!this.persistenceAuthorized){this.topologyEnsureBaseline();return false;}this.ensurePersistence();if(!fs.existsSync(this.stateFile)){this.topologyEnsureBaseline();return false;}this.state={...this.state,...JSON.parse(fs.readFileSync(this.stateFile,'utf8')),condition:'loaded',state:'idle'};if(!this.state.topology)this.state.topology={schema:TOPOLOGY_SCHEMA,facilities:[],assets:[],allocations:[],facilitySequence:0,assetSequence:0,allocationSequence:0};if(!this.state.security)this.state.security={schema:SECURITY_SCHEMA,domains:SECURITY_DOMAINS,decisions:[]};if(!this.state.controlBoundaries)this.state.controlBoundaries={schema:CONTROL_BOUNDARY_SCHEMA,crossings:[]};if(!this.state.information)this.state.information={schema:INFORMATION_FLOW_SCHEMA,objects:[],flows:[],objectSequence:0,flowSequence:0};if(!this.state.identityAuthority)this.state.identityAuthority={schema:IDENTITY_SCHEMA,identities:[],credentials:[],assignments:[],delegations:[],decisions:[]};if(!this.state.goals)this.state.goals={schema:GOALS_SCHEMA,definitions:CONSTRUCTIVE_GOALS,evidence:[]};this.topologyEnsureBaseline();return true;}
  save(){if(!this.persistenceAuthorized)return null;this.ensurePersistence();this.state.updatedAt=new Date().toISOString();const t=`${this.stateFile}.${process.pid}.${tfUuidGenerate()}.tmp`;try{fs.writeFileSync(t,`${JSON.stringify(this.state,null,2)}\n`,{mode:0o600,flag:'wx'});fs.renameSync(t,this.stateFile);}finally{try{if(fs.existsSync(t))fs.unlinkSync(t);}catch{}}return this.stateFile;}
  resolveLocal(p){if(typeof p!=='string'||!p.trim())throw new Error('Path must be a non-empty string');const resolved=path.resolve(this.root,p);const rel=path.relative(this.root,resolved);if(rel.startsWith('..')||path.isAbsolute(rel))throw new Error('Path escapes Terraformer root');return resolved;}
