  transform(plan,src){let out=src.data;if(plan.domain==='text'){let text=src.data.toString('utf8');if(plan.operation==='uppercase')text=text.toUpperCase();if(plan.operation==='lowercase')text=text.toLowerCase();if(plan.operation==='trim')text=text.trim();if(plan.operation==='normalize-lines')text=text.replace(/\r\n?/g,'\n');out=Buffer.from(text,'utf8');}else if(plan.domain==='json'&&plan.operation!=='copy'){const value=JSON.parse(src.data.toString('utf8'));out=Buffer.from(plan.operation==='format'?JSON.stringify(value,null,2)+'\n':JSON.stringify(value),'utf8');}else if(plan.domain==='markdown'&&plan.operation!=='copy'){let text=src.data.toString('utf8').replace(/\r\n?/g,'\n');if(plan.operation==='ensure-final-newline')text=text.replace(/\n*$/,'\n');out=Buffer.from(text,'utf8');}return {stage:'transform',domain:plan.domain,data:out,bytes:out.length,sha256:crypto.createHash('sha256').update(out).digest('hex')};}
  target(plan,tx){if(!this.persistenceAuthorized)throw new Error('Persistence boundary: transform target requires explicit --persist authorization');fs.mkdirSync(path.dirname(plan.target),{recursive:true});let recovery=null;if(fs.existsSync(plan.target)){const old=fs.readFileSync(plan.target);const name=`${Date.now()}-${tfUuidGenerate()}-${path.basename(plan.target)}.bak`;recovery=path.join(this.recoveryDir,name);fs.writeFileSync(recovery,old,{mode:0o600});}const temp=`${plan.target}.terraformer-${process.pid}.tmp`;try{fs.writeFileSync(temp,tx.data,{mode:0o600,flag:'wx'});fs.renameSync(temp,plan.target);}catch(e){try{if(fs.existsSync(temp))fs.unlinkSync(temp);}catch{}throw e;}return {stage:'target',path:plan.target,recovery};}
