  restore(backup,target){this.persistenceAuthorized=true;this.load();const b=this.resolveLocal(backup),t=this.resolveLocal(target);if(!b.startsWith(this.recoveryDir+path.sep))throw new Error('Backup must be inside the recovery area');if(!fs.existsSync(b))throw new Error('Recovery backup does not exist');const tmp=`${t}.terraformer-restore-${process.pid}.tmp`;fs.mkdirSync(path.dirname(t),{recursive:true});fs.copyFileSync(b,tmp,fs.constants.COPYFILE_EXCL);fs.renameSync(tmp,t);const result={stage:'recovery',ok:true,backup:b,target:t};this.state.lastResult={...result,time:new Date().toISOString()};this.save();return result;}
  canonical(value){if(Array.isArray(value))return value.map(v=>this.canonical(v));if(value&&typeof value==='object'){const out={};for(const k of Object.keys(value).sort())out[k]=this.canonical(value[k]);return out;}return value;}
  registerProviders(){for(const [name,p] of Object.entries(PROVIDERS))this.providerRuntime[name]={name,state:'registered',healthy:false,capabilities:[...p.capabilities],initializedAt:null,checkedAt:null,error:null};}
  initializeProvider(name='local'){const p=PROVIDERS[name];if(!p)throw new Error(`Unsupported provider: ${name}`);const r=this.providerRuntime[name]||(this.providerRuntime[name]={name,state:'registered',healthy:false,capabilities:[...p.capabilities]});try{r.state='initialized';r.initializedAt=new Date().toISOString();if(name==='local'){if(!fs.existsSync(this.root)||!fs.statSync(this.root).isDirectory())throw new Error('Terraformer root is unavailable');}r.state='healthy';r.healthy=true;r.checkedAt=new Date().toISOString();r.error=null;return {...r};}catch(e){r.state='failed';r.healthy=false;r.checkedAt=new Date().toISOString();r.error=e.message;throw e;}}
