  providerLifecycle(){for(const name of Object.keys(PROVIDERS))if(this.providerRuntime[name].state==='registered')this.initializeProvider(name);return {model:'provider-lifecycle',states:PROVIDER_STATES,providers:this.providerRuntime};}
  openProviderSession(name,capability,context={}){this.requireCapability(name,capability);const now=new Date().toISOString();const session={id:tfUuidGenerate(),model:'provider-session',provider:name,capability,state:'open',openedAt:now,closedAt:null,context:this.canonical(context),input:null,output:null,error:null};return session;}
  closeProviderSession(session,output,error=null){session.closedAt=new Date().toISOString();session.state=error?'failed':'closed';session.error=error?String(error.message||error):null;session.output=output===undefined?null:this.canonical(output);return session;}
