  providerSessionDescribe(){return {model:'provider-session-contract',states:['open','closed','failed'],identity:'UUID',scope:['provider','capability','resource'],authority:'inherits-existing-capability-and-apply-boundaries',evidence:['openedAt','closedAt','input','output','error']};}
  providerForResource(resource,capability='validate'){const def=RESOURCE_TYPES[resource.type];if(!def)throw new Error(`Unsupported resource type: ${resource.type}`);const name=resource.provider||def.provider;return this.requireCapability(name,capability);}
  adapterForResource(resource){const def=RESOURCE_TYPES[resource.type];const provider=this.providerForResource(resource);if(!provider.resourceTypes.includes(resource.type))throw new Error(`Provider ${provider.name} does not support resource type: ${resource.type}`);return {provider:provider.name,adapter:def.adapter,type:resource.type,capabilities:provider.capabilities};}
  providerDescribe(){this.providerLifecycle();return {model:'provider-registry',lifecycleStates:PROVIDER_STATES,runtime:this.providerRuntime,providers:PROVIDERS,resourceAdapters:Object.fromEntries(Object.entries(RESOURCE_TYPES).map(([type,d])=>[type,{provider:d.provider,adapter:d.adapter,properties:d.properties}]))};}
  resourceId(resource){if(!resource||typeof resource!=='object'||Array.isArray(resource))throw new Error('Resource must be an object');const type=resource.type,name=resource.name;if(!RESOURCE_TYPES[type])throw new Error(`Unsupported resource type: ${type}`);if(typeof name!=='string'||!name.trim())throw new Error('Resource name must be a non-empty string');return `${type}.${name.trim()}`;}
  normalizeResource(resource){const id=this.resourceId(resource);const type=resource.type;const allowed=new Set(RESOURCE_TYPES[type].properties);const properties=resource.properties??{};if(!properties||typeof properties!=='object'||Array.isArray(properties))throw new Error(`Resource properties must be an object: ${id}`);for(const key of Object.keys(properties))if(!allowed.has(key))throw new Error(`Unsupported property for ${type}: ${key}`);const dependsOn=resource.dependsOn??[];if(!Array.isArray(dependsOn)||dependsOn.some(x=>typeof x!=='string'||!x.trim()))throw new Error(`dependsOn must be an array of resource IDs: ${id}`);const state=resource.state??'present';if(!['present','absent'].includes(state))throw new Error(`Resource state must be present or absent: ${id}`);const adapter=this.adapterForResource(resource);return this.canonical({id,type,name:resource.name.trim(),provider:adapter.provider,adapter:adapter.adapter,state,properties,dependsOn:[...new Set(dependsOn)].sort()});}
