  orderResources(resources){const byId=new Map(resources.map(r=>[r.id,r]));const visiting=new Set(),visited=new Set(),ordered=[];const visit=id=>{if(visited.has(id))return;if(visiting.has(id))throw new Error(`Dependency cycle detected at ${id}`);visiting.add(id);for(const dep of byId.get(id).dependsOn)visit(dep);visiting.delete(id);visited.add(id);ordered.push(byId.get(id));};for(const id of [...byId.keys()].sort())visit(id);return ordered;}
