  planResources(desiredFile,currentFile){const desired=JSON.parse(fs.readFileSync(this.resolveLocal(desiredFile),'utf8'));const current=currentFile?JSON.parse(fs.readFileSync(this.resolveLocal(currentFile),'utf8')):[];return this.resourcePlan(desired,current);}
