  applyResources(desiredInput,currentInput=[],authorized=false){this.requireCapability('local','apply');if(authorized!==true)throw new Error('Resource apply requires explicit authorization');this.persistenceAuthorized=true;const desired=this.normalizeResourceSet(desiredInput),current=this.normalizeResourceSet(currentInput),plan=this.resourcePlan(desired,current),byDesired=new Map(desired.map(r=>[r.id,r])),byCurrent=new Map(current.map(r=>[r.id,r]));this.ensurePersistence();const txid=tfUuidGenerate(),txdir=path.join(this.recoveryDir,'resource-'+txid);fs.mkdirSync(txdir,{recursive:true});const journal={id:txid,model:'resource-transaction',startedAt:new Date().toISOString(),state:'applying',plan,steps:[]};const journalFile=path.join(txdir,'journal.json');const saveJournal=()=>fs.writeFileSync(journalFile,JSON.stringify(journal,null,2)+'\n',{mode:0o600});saveJournal();try{for(const change of plan.changes){if(change.action==='no-op')continue;const r=byDesired.get(change.id)||byCurrent.get(change.id);const snap=this.snapshotResource(r,txdir);journal.steps.push({id:change.id,action:change.action,snapshot:snap,status:'prepared'});saveJournal();if(change.action==='delete')this.removeResource(r);else this.writeResource(r);journal.steps.at(-1).status='applied';saveJournal();}for(const r of desired)if(!this.verifyResource(r))throw new Error(`Post-apply verification failed: ${r.id}`);journal.state='committed';journal.completedAt=new Date().toISOString();saveJournal();this.load();this.state.resourceTransactions=(this.state.resourceTransactions||0)+1;this.state.lastResult={stage:'resource-apply',ok:true,transaction:txid,journal:journalFile,time:new Date().toISOString()};this.save();return {model:'resource-apply',ok:true,transaction:txid,journal:journalFile,summary:plan.summary,verified:true};}catch(error){journal.state='rolling-back';journal.error=error.message;saveJournal();for(const step of [...journal.steps].reverse()){const r=byDesired.get(step.id)||byCurrent.get(step.id);try{this.restoreSnapshot(r,step.snapshot);step.status='rolled-back';}catch(e){step.status='rollback-failed';step.rollbackError=e.message;}}journal.state=journal.steps.some(x=>x.status==='rollback-failed')?'rollback-failed':'rolled-back';journal.completedAt=new Date().toISOString();saveJournal();throw error;}}
  observeResource(resource){const providerName=resource.provider||RESOURCE_TYPES[resource.type]?.provider||'local';const r=this.normalizeResource(resource);const routed=this.withProviderSession(providerName,'discover',{resource:r.id,type:r.type},()=>{const target=this.resourcePath(r);if(!fs.existsSync(target))return this.canonical({...r,state:'absent',properties:r.properties});const st=fs.lstatSync(target);if(r.type==='directory'){if(!st.isDirectory())throw new Error(`Observed kind mismatch for ${r.id}: expected directory`);return this.canonical({...r,state:'present',properties:{...r.properties,mode:st.mode&0o777}});}if(!st.isFile())throw new Error(`Observed kind mismatch for ${r.id}: expected file`);const encoding=r.properties.encoding||'utf8',content=fs.readFileSync(target,encoding);const properties={...r.properties,content};if(r.type==='file'){properties.encoding=encoding;properties.mode=st.mode&0o777;}return this.canonical({...r,state:'present',properties});});this.lastProviderSession=routed.session;return routed.output;}
