  runtimeFabric(){if(!this._runtimeFabric)this._runtimeFabric=buildRuntimeFabric(this.systemList(),this.workerList());return this._runtimeFabric;}
  workerGet(q){const n=String(q).toLowerCase();return this.workerList().find(w=>w.id.toLowerCase()===n||w.key.toLowerCase()===n||w.name.toLowerCase()===n)||null;}
  fabricDispatch(systemQuery,workerQuery,capability='execution',payload=null){const systems=this.systemList(),sys=systems.find(x=>[x.id,x.key,x.name].filter(Boolean).some(v=>String(v).toLowerCase()===String(systemQuery).toLowerCase()));if(!sys)throw new Error('unknown fabric system');const fabric=this.runtimeFabric(),rels=fabric.relations.filter(r=>r.systemId===sys.id),domain=String(capability).replace(/^(domain:|work:)/,'');let eligible=rels.filter(r=>r.domains.includes(domain)||r.domains.includes('control'));if(workerQuery){const w=this.workerGet(workerQuery);if(!w)throw new Error('unknown fabric worker');eligible=eligible.filter(r=>r.workerId===w.id);}eligible.sort((a,b)=>a.workerKey.localeCompare(b.workerKey));if(!eligible.length)throw new Error('semantic route rejected');const rel=eligible[0],w=this.workerGet(rel.workerId),farm=fabric.farms.find(f=>f.domains.includes(domain))||fabric.farms[0],pool=farm.pools[0],correlationId=tfUuidGenerate(),workId='TFWORK-'+String((this.state.fabricTransactions||0)+1).padStart(6,'0'),stages=fabric.flow.map((stage,i)=>({ordinal:i+1,stage,state:i===fabric.flow.length-1?'completed':'passed'}));const tx={schema:RUNTIME_FABRIC_SCHEMA,workId,correlationId,system:{id:sys.id,name:sys.name},worker:{id:w.id,key:w.key,name:w.name},capability:domain,relation:rel,farmId:farm.id,poolId:pool.id,lane:pool.lanes[0],payload,pipeline:stages,status:'completed',authority:'observational runtime-fabric transaction; no privilege or filesystem authority expansion',time:new Date().toISOString()};this.state.fabricTransactions=(this.state.fabricTransactions||0)+1;this.state.lastFabricTransaction=tx;this.save();return tx;}
