  async fabricPoolBatch(systemQuery,workerQuery,capability='execution',operation='echo',count=POOL_SIZE*2){const total=Math.max(1,Math.min(Number(count)||1,POOL_QUEUE_LIMIT));const startedAt=new Date().toISOString();const jobs=[];for(let i=0;i<total;i++)jobs.push(this.fabricDispatchConcurrent(systemQuery,workerQuery,capability,{batchIndex:i},operation));const settled=await Promise.allSettled(jobs);const completed=settled.filter(x=>x.status==='fulfilled').length,failed=settled.length-completed;return {schema:WORKER_POOL_SCHEMA,startedAt,completedAt:new Date().toISOString(),requested:total,completed,failed,pool:workerPool().status(),results:settled.map((x,i)=>x.status==='fulfilled'?{index:i,status:'completed',workId:x.value.workId,poolSlot:x.value.execution.poolSlot,generation:x.value.execution.generation}:{index:i,status:'failed',error:x.reason?.message||String(x.reason)})};}
