  systemList(){return [...Object.values(SYSTEM_REGISTRY).map(x=>this.canonical(x)),...TERRAFORMER_MEMBER_SERVICE_SYSTEMS.map(x=>this.canonical(x)),...([TERRAFORMER_FILE_SYSTEM,TERRAFORMER_FILE_MANAGER,TERRAFORMER_PRELOAD_SYSTEM,TERRAFORMER_PRELAUNCH_SYSTEM,TERRAFORMER_SELF_PLACEMENT,TERRAFORMER_PRIVILEGE_BROKER,TERRAFORMER_SUSTAINMENT,TERRAFORMER_OBSERVATION,TERRAFORMER_DECISION,TERRAFORMER_QUIESCENCE,TERRAFORMER_PACIFICATION,TERRAFORMER_CONSCIOUSNESS,TERRAFORMER_AWARENESS,TERRAFORMER_INTELLIGENCE,TERRAFORMER_PROPAGATION,TERRAFORMER_NEURAL]).map(x=>this.canonical(x)),...CHAT_SYSTEMS.map(x=>this.canonical(x)),...TELEGRAM_SYSTEMS.slice(1).map(x=>this.canonical(x)),...WHATSAPP_SYSTEMS.map(x=>this.canonical(x)),...LOCALHOST_V068_SYSTEMS.map(x=>this.canonical({...x,state:'registered',qualification:'Under Conditional Experiment'}))];}
