  topologyEnsureBaseline(){const t=this.state.topology||(this.state.topology={schema:TOPOLOGY_SCHEMA,facilities:[],assets:[],allocations:[],facilitySequence:0,assetSequence:0,allocationSequence:0});if(t.facilities.length)return t;const specs=[['realm.center','area.operations','zone.telegram','site.processing','Operations Center Facility'],['realm.data-center','area.operations','zone.telegram','site.processing','Data Center Facility'],['realm.ground','area.operations','zone.telegram','site.processing','Ground Operations Facility'],['realm.on-site','area.operations','zone.telegram','site.processing','On-Site Operations Facility'],['realm.remote','area.operations','zone.telegram','site.processing','Remote Operations Facility']];for(const [realm,area,zone,site,name] of specs){const f=this.facilityCreate({realm,area,zone,site,name,save:false});this.assetCreate({facilityId:f.id,name:name+' Compute Capacity',kind:'compute-slot',capacity:SCHEDULER_CAPACITY,save:false});}return t;}
  facilityCreate(spec={}){const t=this.state.topology;const realm=spec.realm||'realm.center';if(!OPERATION_REALMS.some(x=>x.id===realm))throw new Error('unknown facility realm');t.facilitySequence=(t.facilitySequence||0)+1;const f={schema:FACILITY_SCHEMA,id:'TFFAC-'+String(t.facilitySequence).padStart(6,'0'),name:String(spec.name||'Facility'),parentId:spec.parentId||null,realm,area:spec.area||'area.general',zone:spec.zone||'zone.general',site:spec.site||'site.processing',state:spec.state||'available',health:'healthy',createdAt:new Date().toISOString()};t.facilities.push(f);if(spec.save!==false)this.save();return this.canonical(f);}
