  topologyFindFacility(envelope={}){const t=this.state.topology;return t.facilities.find(f=>f.realm===envelope.realm&&f.area===envelope.area&&f.zone===envelope.zone&&f.site===envelope.site)||t.facilities.find(f=>f.realm===envelope.realm)||null;}
