  topologyRelease(operationId){const t=this.state.topology,open=t.allocations.filter(x=>x.operationId===operationId&&x.state==='allocated');for(const x of open){const a=t.assets.find(v=>v.id===x.assetId);if(a){a.allocated=Math.max(0,a.allocated-x.units);a.available=Math.max(0,a.capacity-a.allocated);a.state=a.maintenance?'maintenance':a.health==='healthy'?'available':'degraded';}x.state='released';x.releasedAt=new Date().toISOString();}if(open.length)this.save();return open.length;}
  assetSetState(id,state){const a=this.state.topology.assets.find(x=>x.id===id);if(!a)throw new Error('unknown asset');if(!ASSET_STATES.includes(state))throw new Error('invalid asset state');a.state=state;a.maintenance=state==='maintenance';a.health=state==='degraded'?'degraded':state==='unavailable'?'unavailable':'healthy';this.save();return this.canonical(a);}
