  delegationCreate(input={}){const from=String(input.from||''),to=String(input.to||''),capability=String(input.capability||'');if(!this.state.identityAuthority.identities.find(x=>x.id===from)||!this.state.identityAuthority.identities.find(x=>x.id===to))throw new Error('delegation identities must exist');if(!capability)throw new Error('delegation capability required');const parent=input.parentId?this.state.identityAuthority.delegations.find(x=>x.id===input.parentId):null;if(input.parentId&&!parent)throw new Error('unknown parent delegation');const now=Date.now(),expiresAt=input.expiresAt||new Date(now+3600000).toISOString();if(Date.parse(expiresAt)<=now)throw new Error('delegation expiry must be future');const rec={id:'TFDEL-'+tfUuidGenerate(),from,to,capability,scope:String(input.scope||'terraformer'),parentId:parent?.id||null,state:'ACTIVE',createdAt:new Date(now).toISOString(),expiresAt,revokedAt:null};this.state.identityAuthority.delegations.push(rec);this.save();return this.canonical(rec);}
