  authorityEvaluate(identityId,capability,scope='terraformer'){const now=Date.now(),assignments=this.state.identityAuthority.assignments.filter(a=>a.identityId===identityId&&a.state==='ACTIVE'&&(a.scope===scope||a.scope==='terraformer')),roleCaps=assignments.flatMap(a=>ROLE_DEFINITIONS.find(r=>r.id===a.roleId)?.capabilities||[]),delegations=this.state.identityAuthority.delegations.filter(d=>{if(!(d.to===identityId&&d.capability===capability&&d.state==='ACTIVE'&&Date.parse(d.expiresAt)>now&&(d.scope===scope||d.scope==='terraformer')))return false;let cur=d,seen=new Set();while(cur.parentId){if(seen.has(cur.id))return false;seen.add(cur.id);const parent=this.state.identityAuthority.delegations.find(x=>x.id===cur.parentId);if(!parent||parent.state!=='ACTIVE'||parent.capability!==capability||Date.parse(parent.expiresAt)<=now)return false;cur=parent;}return true;});const admitted=roleCaps.includes(capability)||delegations.length>0,decision={id:'TFAUTH-'+tfUuidGenerate(),identityId,capability,scope,admitted,source:roleCaps.includes(capability)?'role':delegations.length?'delegation':'none',time:new Date().toISOString()};this.state.identityAuthority.decisions.push(decision);this.save();return this.canonical(decision);}
  identityAuthorityStatus(){return this.canonical({schema:IDENTITY_SCHEMA,identityTypes:IDENTITY_TYPES,roles:ROLE_DEFINITIONS,identities:this.state.identityAuthority.identities,credentials:this.state.identityAuthority.credentials.map(c=>({...c,secretStored:false})),assignments:this.state.identityAuthority.assignments,delegations:this.state.identityAuthority.delegations,decisions:this.state.identityAuthority.decisions.slice(-50),principles:['credentials are references/fingerprints only; no secrets stored','roles grant only declared capabilities','delegation is capability-and-scope bounded','expiry and revocation fail closed','delegation cannot bypass security, information-flow or qualification controls']});}
  goalEvaluate(input={}){const goodwillChildren={philanthropy:Boolean(input.beneficialOutcome&&input.publicInterest),charity:Boolean(input.voluntaryContribution&&input.declaredBeneficiary&&input.directAidSupport&&input.deliveryEvidence),beneficence:Boolean(input.beneficialIntent&&input.avoidUnnecessaryHarm),stewardship:Boolean(input.responsibleCare&&input.entrustedAssetsProtected),reciprocity:Boolean(input.mutualExchange&&input.nonConditionalAssistance),solidarity:Boolean(input.sharedNeedSupport&&input.legitimateNeed),civicContribution:Boolean(input.communityBenefit&&input.sharedInfrastructureContribution),accessibility:Boolean(input.barrierReduction&&input.legitimateAccess),sustainability:Boolean(input.continuityPreserved&&input.depletionAvoided&&input.damageAvoided),humanitarianSupport:Boolean(input.humanWelfare&&input.reliefSafetyBasicNeeds)};const metrics={goodwill:Object.values(goodwillChildren).every(Boolean),...goodwillChildren,affinity:Boolean(input.compatibleCooperation&&input.relationshipAligned),conformity:Boolean(input.specificationConformant&&input.policyConformant&&input.boundaryConformant)};const rec={id:'TFGOAL-'+tfUuidGenerate(),schema:GOALS_SCHEMA,time:new Date().toISOString(),metrics,allSatisfied:Object.values(metrics).every(Boolean),authorityEffect:'none',evidence:this.canonical(input.evidence||{})};this.state.goals.evidence.push(rec);this.save();return this.canonical(rec);}
  goalsStatus(){return this.canonical({schema:GOALS_SCHEMA,definitions:CONSTRUCTIVE_GOALS,evidence:this.state.goals.evidence.slice(-50),principle:'goals guide and measure constructive outcomes; they never create authorization, clearance, credential, classification or execution privilege'});}
