  informationCreate(input={}){const level=String(input.classification||'PUBLIC').toUpperCase();if(!CLASSIFICATION_LEVELS.includes(level))throw new Error('unknown classification level');const id='TFINFO-'+String(++this.state.information.objectSequence).padStart(6,'0'),now=new Date().toISOString();const obj={schema:INFORMATION_OBJECT_SCHEMA,id,origin:input.origin||'terraformer',classification:level,compartments:[...new Set(input.compartments||[])].sort(),contentType:input.contentType||'application/octet-stream',contentHash:input.contentHash||null,derivedFrom:input.derivedFrom||null,history:[{event:'created',classification:level,time:now}],createdAt:now};this.state.information.objects.push(obj);this.save();return this.canonical(obj);}
