  defaultEntryHTML(){
    return '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Terraformer — Default</title><style>*{box-sizing:border-box}html,body{height:100%;margin:0}body{display:grid;place-items:center;background:#181c21;color:#eee;font-family:system-ui,-apple-system,Segoe UI,sans-serif}.entry{text-align:center;max-width:560px;padding:40px}.entry h1{font-size:34px;margin:0 0 12px}.entry p{color:#aeb7c1;line-height:1.6}.entry button{margin-top:20px;padding:12px 34px;border:1px solid #697582;border-radius:7px;background:#252b32;color:#fff;font:inherit;font-weight:650;cursor:pointer}.entry button:hover,.entry button:focus{background:#38414b;outline:2px solid #8995a2;outline-offset:2px}</style></head><body><main class="entry"><h1>Terraformer</h1><p>Default entry surface. The active construction environment is isolated behind an explicit entry crossing.</p><button id="enter" type="button">Enter</button></main><script>document.getElementById("enter").addEventListener("click",()=>{const mobile=matchMedia("(max-width:768px), (pointer:coarse) and (max-width:1024px)").matches;location.assign(mobile?"/mdefault":"/default2")});</script></body></html>';
  }
